import hashlib
import binascii


def task_func(salt, cursor):
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")

    def quote_ident(name: str) -> str:
        return '"' + name.replace('"', '""') + '"'

    def hash_password(password: str) -> str:
        digest = hashlib.sha256((salt + password).encode("utf-8")).digest()
        return binascii.hexlify(digest).decode("ascii")

    password_columns = ("password", "passwd", "pwd", "pass")
    preferred_tables = ("users", "user")

    cursor.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
    )
    tables = [row[0] for row in cursor.fetchall()]

    selected_table = None
    selected_password_col = None
    selected_pk_cols = []

    candidates = list(preferred_tables) + [t for t in tables if t not in preferred_tables]

    for table in candidates:
        try:
            cursor.execute(f"PRAGMA table_info({quote_ident(table)})")
            info = cursor.fetchall()
        except Exception:
            continue

        col_names = [row[1] for row in info]
        pk_cols = [row[1] for row in sorted(info, key=lambda r: r[5]) if row[5] > 0]

        for pwd_col in password_columns:
            if pwd_col in col_names:
                selected_table = table
                selected_password_col = pwd_col
                selected_pk_cols = pk_cols
                break

        if selected_table is not None:
            break

    if selected_table is None or selected_password_col is None:
        return 0

    if selected_pk_cols:
        select_cols = ", ".join(quote_ident(col) for col in selected_pk_cols + [selected_password_col])
        cursor.execute(f"SELECT {select_cols} FROM {quote_ident(selected_table)}")
        rows = cursor.fetchall()

        updated = 0
        for row in rows:
            *pk_values, password = row
            if password is None:
                continue

            new_password = hash_password(str(password))
            where_clause = " AND ".join(f"{quote_ident(col)}=?" for col in selected_pk_cols)
            cursor.execute(
                f"UPDATE {quote_ident(selected_table)} SET {quote_ident(selected_password_col)}=? "
                f"WHERE {where_clause}",
                (new_password, *pk_values),
            )
            updated += 1
    else:
        cursor.execute(
            f"SELECT rowid, {quote_ident(selected_password_col)} FROM {quote_ident(selected_table)}"
        )
        rows = cursor.fetchall()

        updated = 0
        for rowid, password in rows:
            if password is None:
                continue

            new_password = hash_password(str(password))
            cursor.execute(
                f"UPDATE {quote_ident(selected_table)} SET {quote_ident(selected_password_col)}=? "
                f"WHERE rowid=?",
                (new_password, rowid),
            )
            updated += 1

    try:
        cursor.connection.commit()
    except Exception:
        pass

    return updated
